/// <summary>
/// MPJ_11539 - kscerri - 27/07/2021
/// Class <c>METCustTransListingController</c> controller
/// </summary>
class METCustActivityStatementController extends SrsPrintMgmtController implements BatchRetryable
{
    METCustActivityStatementContract contract;
    METLinkedCustAccountTmp     LinkedCustAccountTmp;
    METLinkedCustAccountTmp     LinkedCustAccountTmpParent;

    //Data tables
    METCustActivityStatementTmp             custActivityStatementHeader;
    METCustActivityStatementInvoiceLinesTmp custActivityStatementLines;

    CreatedTransactionId        createdTransactionId, createdHeaderTransactionId;

}

Method.Source:
/// <summary>
/// MPJ_11539 - kscerri - 27/07/2021
/// constructor
/// </summary>
/// <returns>constructor</returns>
public static METCustActivityStatementController construct()
{
    return new METCustActivityStatementController();
}

/// <summary>
/// MPJ_11539 - kscerri - 08/04/2021
/// Main method to run report
/// </summary>
/// <param name = "_args">args</param>
public static void main(Args _args)
{
    SrsPrintMgmtController controller  = METCustActivityStatementController::construct();
    controller.parmReportName(PrintMgmtDocType::construct(PrintMgmtDocumentType::METCustActivityStatement).getDefaultReportFormat());
    controller.parmArgs(_args);
    controller.parmDialogCaption("@MET:CustActivityStatement");
    controller.startOperation();
}

    /// <summary>
    /// MPJ_11539 - kscerri - 08/04/2021
    /// setup print managment setup
    /// </summary>
    protected void initPrintMgmtReportRun()
    {
        printMgmtReportRun = printMgmtReportRun::construct( PrintMgmtHierarchyType::Sales,
                                                            PrintMgmtNodeType::Sales,
                                                            PrintMgmtDocumentType::METCustActivityStatement);

        printMgmtReportRun.parmReportRunController(this);

        super();
    }

    /// <summary>
    /// Load print management
    /// </summary>
    /// <param name = "_custTableParent">CustTable record</param>
    private void loadPrintMgmtReportRun(CustTable _custTableParent)
    {
        CustLanguageId custLanguageId = this.getCustomerLanguage(_custTableParent);

        printMgmtReportRun.load(_custTableParent, _custTableParent, custLanguageId);
    }

/// <summary>
/// Find the Language of the customer
/// </summary>
/// <param name = "_custTable">CustTable record</param>
/// <returns>Language Id of the customer</returns>
private CustLanguageId getCustomerLanguage(CustTable _custTable)
{
    CustLanguageId custLanguageId = _custTable.languageId();
    return custLanguageId ? custLanguageId : CompanyInfo::languageId();
}

/// <summary>
/// Initialize the print management settings
/// </summary>
/// <param name = "_custTableParent">CustTable record</param>
private void initPrintMgmtDestinationSettings(CustTable _custTableParent)
{
    if (contract.parmUsePrintManagement())
    {
        this.loadPrintMgmtReportRun(_custTableParent);
    }
    else
    {
        this.loadDefaultSRSPrintDestinationSettings();
    }
}

    /// <summary>
    /// Load SSRS settings
    /// </summary>
    private void loadDefaultSRSPrintDestinationSettings()
    {
        PrintMgmtDocInstanceType docInstanceType = PrintMgmtDocInstanceType::Original;

        PrintMgmtReportFormat printMgmtReportFormat;
        printMgmtReportFormat = PrintMgmtReportFormat::findSystem(PrintMgmtDocumentType::METCustActivityStatement);

        PrintMgmtPrintSettingDetail printSettingDetail = new PrintMgmtPrintSettingDetail();
        printSettingDetail.parmReportFormatName(printMgmtReportFormat.Name);
        printSettingDetail.parmSSRS(printMgmtReportFormat.SSRS);
        printSettingDetail.parmType(docInstanceType);
        printSettingDetail.parmInstanceName(enum2str(docInstanceType));
        printSettingDetail.parmNumberOfCopies(1);
        printSettingDetail.parmPrintJobSettings(this.getDefaultSRSPrintDestinationSettings());

        printMgmtReportRun.loadSettingDetail(printSettingDetail);
    }

    /// <summary>
    /// Get SSRS settings
    /// </summary>
    /// <returns>SSRS settings</returns>
    private SRSPrintDestinationSettings getDefaultSRSPrintDestinationSettings()
    {
        SRSPrintDestinationSettings printDestinationSetting = new SRSPrintDestinationSettings();
        printDestinationSetting = this.getDataContractObject('SRSPrintDestinationSettings') as SRSPrintDestinationSettings;

        return printDestinationSetting;
    }

    /// <summary>
    /// MPJ_11539 - kscerri - 08/04/2021
    /// Run print mgmt report depending on metcusttrans accounts
    /// </summary>
    protected void runPrintMgmt()
    {
        contract = this.parmContract();

        // Company list
        container selectedCompanyList = METCustActivityStatementController::getSelectedCompanyList(query, curext());

        if (conLen(selectedCompanyList) > 0)
        {
            var customerQueryRun = new QueryRun(query);
            boolean isEncounteredException = false;
            
            this.populateLinkedCustAccountTables(customerQueryRun);

            CustTable custTable;
            CustTable custTableParent;
    
            while select LinkedCustAccountNum, LinkedLegalEntity
                from    LinkedCustAccountTmpParent
                group by LinkedCustAccountNum asc, LinkedLegalEntity
                where   LinkedCustAccountTmpParent.Parent == NoYes::Yes
            {
                changecompany(LinkedCustAccountTmpParent.LinkedLegalEntity)
                {
                    custTableParent = CustTable::find(LinkedCustAccountTmpParent.LinkedCustAccountNum);
                }
                                
                createdTransactionId = 0;
                createdHeaderTransactionId = 0;

                try
                {
                    ttsbegin;

                    while select LinkedCustAccountTmp
                        order by Parent desc, LinkedCustAccountNum asc
                        where   LinkedCustAccountTmp.LinkedCustAccountNum   == LinkedCustAccountTmpParent.LinkedCustAccountNum
                        &&      LinkedCustAccountTmp.LinkedLegalEntity      == LinkedCustAccountTmpParent.LinkedLegalEntity
                        &&      LinkedCustAccountTmp.AddressOnly            == NoYes::No
                    {
                        selectedCompanyList = conNull();
                        selectedCompanyList = [LinkedCustAccountTmp.LegalEntity];

                        changecompany(LinkedCustAccountTmp.LegalEntity)
                        {
                            custTable = CustTable::find(LinkedCustAccountTmp.CustAccountNum);
                            setPrefix(strFmt("@AccountsReceivable:CustAccountNumber", custTable.AccountNum));
                        }

                        //process transactions for the Customer
                        this.processParty(custTable, LinkedCustAccountTmp.LegalEntity);
                    }
                    
                    ttscommit;

                    // only run the report if any data was inserted
                    if (createdTransactionId)
                    {
                        this.initPrintMgmtReportRun();
                        this.initPrintMgmtDestinationSettings(custTableParent);

                        CustLanguageId languageId = this.getCustomerLanguage(custTableParent);

                        this.parmReportContract().parmRdlContract().parmLanguageId(languageId);
                        this.parmReportContract().parmRdlContract().parmLabelLanguageId(languageId);
                        
                        this.populateHeader(custTableParent);

                        this.parmContract().parmCSAccountNum(custTableParent.AccountNum);
                        this.parmContract().parmRecordId(createdTransactionId);
                        this.parmContract().parmHeaderRecordId(createdHeaderTransactionId);
                        this.parmContract().parmCustActivityStatementLines(custActivityStatementLines.getPhysicalTableName());
                        this.parmContract().parmCustActivityStatementHeader(custActivityStatementHeader.getPhysicalTableName());
                        
                        this.outputReports();
                    }
                }
                catch
                {
                    isEncounteredException = true;
                }
                
            }
            if (isEncounteredException)
            {
                //This error has been thrown just to fail the batch after processing all the customers and
                //later on this error message is overwritten by the framework generic message.
                throw Error('');
            }
        }
    }

    /// <summary>
    /// Populate the Party transactions into TMP tables
    /// </summary>
    /// <param name = "_custTable">customer record</param>
    /// <param name = "_dataAreaId">Legal entity</param>
    public void processParty(CustTable _custTable, SelectableDataArea _dataAreaId)
    {
        SelectableDataArea communityChestDataArea = METConstants::CommunityChestLegalEntityId;

        //check if transactions exist. 
        if(this.preProcessCustomer(_custTable, _dataAreaId))
        {
            // Payment lines
            this.paymentLines(_custTable, _dataAreaId);

            // Invoice and trans lines
            this.invoiceLines(_custTable, _dataAreaId);
     
            createdTransactionId = custActivityStatementLines.createdTransactionId;
            
            if (curExt() == communityChestDataArea)
            {
                update_recordset custActivityStatementLines
                setting AmountCur    = custActivityStatementLines.AmountCur * -1,
                        TaxAmountCur = custActivityStatementLines.TaxAmountCur * -1;
            }
        }
    }

    /// <summary>
    /// MPJ_11539 - kscerri - 08/04/2021
    /// Populates header tmp table
    /// </summary>
    /// <param name = "_custTableParent">CustTable record</param>
    public void populateHeader(CustTable _custTableParent)
    {
        //CustTable               custTable;
        CompanyInfo             companyInfo = CompanyInfo::find();
        str                     communityChestDataArea = METConstants::CommunityChestLegalEntityId;

        ttsbegin;

        custActivityStatementHeader.CompanyCoRegNum         = companyInfo.CoRegNum;
        
        custActivityStatementHeader.LinkedCustAccountNum    = _custTableParent.AccountNum;    //contract.parmCSAccountNum();
        custActivityStatementHeader.LinkedLegalEntity       = companyInfo.DataArea;         //legal entity MET where report was run from
        
        changecompany(_custTableParent.DataAreaId)                          //contract.parmCSLegalEntity())
        {
            //custTable = CustTable::find(contract.parmCSAccountNum());
            Image img = CustTable::metGetCustReportLogo(custActivityStatementHeader.LinkedCustAccountNum);
            
            if(img != null)
            {
                custActivityStatementHeader.CompanyLogo = img.getData();
            }
            else
            {
                custActivityStatementHeader.CompanyLogo = CompanyImage::findByRecord(CompanyInfo::find()).Image;
            }
            
            custActivityStatementHeader.CustName            = _custTableParent.name();
            custActivityStatementHeader.CustTable_Address   = DirUtility::replaceAddressTokenLanguage(_custTableParent.statementAddress(), _custTableParent.languageId());
            custActivityStatementHeader.Currency            = _custTableParent.Currency;
            custActivityStatementHeader.KnownAs             = DirPartyTable::findRec(_custTableParent.party).KnownAs;
            custActivityStatementHeader.FooterNote          = contract.parmFooterNote();
            
            METIndustryKeyTable  metIndustryKeyTable = METIndustryKeyTable::find(METCustTable::find(_custTableParent.AccountNum).IndustryKey);
            
            if (metIndustryKeyTable)
            {
                if (metIndustryKeyTable.CoRegNum)
                {
                    custActivityStatementHeader.CompanyCoRegNum = metIndustryKeyTable.CoRegNum;
                }
                if (metIndustryKeyTable.StatementFooterNote)
                {
                    custActivityStatementHeader.FooterNote = metIndustryKeyTable.StatementFooterNote;
                }
            }
        }

        custActivityStatementHeader.ToDate                  = contract.parmToDate();
        custActivityStatementHeader.FromDate                = contract.parmFromDate();
        custActivityStatementHeader.CompanyAddress          = companyInfo.postalAddress().Address;
        
        if (curExt() == communityChestDataArea)
        {
            custActivityStatementHeader.Balance             = _custTableParent.balancePerDate(contract.parmToDate()) * -1;  ///MPJ_20995_Community Chest Activity Statement DCP 01/03/2022
           
        }

        custActivityStatementHeader.insert();

        createdHeaderTransactionId = custActivityStatementHeader.createdTransactionId;
       
        ttscommit;

    }

    /// <summary>
    /// Build Payment lines
    /// </summary>
    /// <param name = "_custTable">CustTable record</param>
    /// <param name = "_dataAreaId">Company Id</param>
    public void paymentLines(CustTable _custTable, SelectableDataArea _dataAreaId)
    {
        CustTrans       custTrans;
        const integer   paymentFlag = 1;
        CustName        custNameStr;

        changecompany(_dataAreaId)
        {
            custNameStr = _custTable.name();

            insert_recordset custActivityStatementLines (AccountNum, TransDate, Txt, PaymReference, Invoice, AmountCur, TransType, Flag, AccountName)

            select AccountNum, TransDate, Txt, PaymReference, Invoice, AmountCur, TransType, paymentFlag, custNameStr
                from    custTrans
                where   custTrans.AccountNum    == _custTable.AccountNum
                &&      custTrans.TransDate     >= contract.parmFromDate()
                &&      custTrans.TransDate     <= contract.parmToDate()
                &&      custTrans.TransType     == LedgerTransType::Payment;
        }
    }

    /// <summary>
    /// Build Invoice lines
    /// </summary>
    /// <param name = "_custTable">CustTable record</param>
    /// <param name = "_dataAreaId">Company Id</param>
    public void invoiceLines(CustTable _custTable, SelectableDataArea _dataAreaId)
    {
        CustTrans        custTrans;
        CustInvoiceTable custInvoiceTable;
        CustInvoiceLine  custInvoiceLine;
        const integer    invoiceFlag = 2;
        CustName         custNameStr;

        changecompany(_dataAreaId)
        {
            custNameStr = _custTable.name();

            while select AccountNum, TransDate, Txt, PaymReference, Invoice, AmountCur, TransType, voucher
                from    custTrans
                where   custTrans.AccountNum    == _custTable.AccountNum
                &&      custTrans.TransDate     >= contract.parmFromDate()
                &&      custTrans.TransDate     <= contract.parmToDate()
                &&      custTrans.TransType     != LedgerTransType::Payment
                &&      custTrans.TransType     != LedgerTransType::Settlement
            {
                custActivityStatementLines.clear();
                
                custActivityStatementLines.accountNum      = custTrans.AccountNum;
                custActivityStatementLines.TransDate       = custTrans.TransDate;
                if (custTrans.TransType ==LedgerTransType::Cust)
                {
                    select firstonly  Description
                        from custInvoiceLine order by LineNum asc
                            join RecId from custInvoiceTable
                                where custInvoiceTable.RecId == CustInvoiceLine.ParentRecId
                                &&    custInvoiceTable.InvoiceId == custTrans.invoice
                                &&    custInvoiceTable.InvoiceAccount == custTrans.Accountnum;

                    custActivityStatementLines.Txt         = custInvoiceLine.Description;
                }
                else
                {
                    custActivityStatementLines.Txt         = custTrans.Txt;
                }
                custActivityStatementLines.PaymReference   = custTrans.PaymReference;
                custActivityStatementLines.Invoice         = custTrans.Invoice;
                custActivityStatementLines.AmountCur       = custTrans.AmountCur;
                custActivityStatementLines.TransType       = custTrans.TransType;
                custActivityStatementLines.GST             = this.calculateGST(custTrans.Voucher, custTrans.TransDate);
                custActivityStatementLines.TaxAmountCur    = custTrans.AmountCur - custActivityStatementLines.GST;
                custActivityStatementLines.Flag            = invoiceFlag;
                custActivityStatementLines.AccountName      = custNameStr;

                custActivityStatementLines.insert();
            }
        }
    }

    /// <summary>
    /// Returns container of selected Companies. Copied from Customer Account Statement
    /// </summary>
    /// <param name = "_query">query from contract class</param>
    /// <param name = "_company">current company</param>
    /// <returns>
    /// Container of selected Companies
    /// </returns>
    private static container getSelectedCompanyList(Query _query, CompanyId _company)
    {
        container queryCompanyRange;
        container queryCompanyRangeList;
        container selectedCompanyList = conNull();
        container sharedCompanyList;
        boolean isShared;
        int i;

        #Define.CompanyPosition(1)
        #Define.IsMarkedPosition(2)

        if (isConfigurationkeyEnabled(configurationKeyNum(CustCentralizedCustStatement)))
        {
            // this retrieves the company range specified by the user on the statement dialog
            queryCompanyRangeList = _query.getCompanyRange();

            sharedCompanyList = CustVendOpenTransManager::findSharedServiceCompanies(_company);

            // include only valid companies in the company list
            for (i = 1; i <= conLen(queryCompanyRangeList); i++)
            {
                queryCompanyRange = conPeek(queryCompanyRangeList, i);

                isShared = conFind(sharedCompanyList, conPeek(queryCompanyRange, #CompanyPosition)) != 0;

                if (conPeek(queryCompanyRange, #IsMarkedPosition) && isShared)
                {
                    selectedCompanyList += conPeek(queryCompanyRange, #CompanyPosition);
                }
            }
        }
        else
        {
            selectedCompanyList += _company;
        }

        return selectedCompanyList;
    }

    /// <summary>
    /// Builds 2 temp tables of Customers and their Parent
    /// </summary>
    /// <param name = "_customerQueryRun">Dialog Query</param>
    public void populateLinkedCustAccountTables(QueryRun _customerQueryRun)
    {
        var customerList = new Set(Types::Int64);

        METCustTable    METCustTable;

        ttsbegin;
            
        while (_customerQueryRun.next())
        {
            CustTable custTable = _customerQueryRun.get(tableNum(CustTable));
                
            // Do not run twice for the same customer
            if (!customerList.in(custTable.RecId))
            {
                setPrefix(strFmt("@AccountsReceivable:CustAccountNumber", CustTable.AccountNum));
                customerList.add(custTable.RecId);

                LinkedCustAccountTmp.clear();
                LinkedCustAccountTmp.CustAccountNum  = custTable.AccountNum;
                LinkedCustAccountTmp.LegalEntity     = CustTable.DataAreaId;
                
                container conCompanies = [LinkedCustAccountTmp.LegalEntity];

                //find Linked account
                select firstonly crosscompany : conCompanies LinkedCustAccountNum, LinkedLegalEntity, RecId
                    from    METCustTable
                    where   METCustTable.AccountNum == LinkedCustAccountTmp.CustAccountNum
                    &&      METCustTable.LinkedCustAccountNum
                    &&      METCustTable.LinkedLegalEntity;

                if(METCustTable.recId)
                {
                    LinkedCustAccountTmp.LinkedCustAccountNum   = METCustTable.LinkedCustAccountNum;
                    LinkedCustAccountTmp.LinkedLegalEntity      = METCustTable.LinkedLegalEntity;
                }
                else
                {
                    LinkedCustAccountTmp.LinkedCustAccountNum   = LinkedCustAccountTmp.CustAccountNum;
                    LinkedCustAccountTmp.LinkedLegalEntity      = LinkedCustAccountTmp.LegalEntity;
                }

                if( LinkedCustAccountTmp.LinkedCustAccountNum == LinkedCustAccountTmp.CustAccountNum
                &&  LinkedCustAccountTmp.LinkedLegalEntity    == LinkedCustAccountTmp.LegalEntity )
                {
                    LinkedCustAccountTmp.Parent = NoYes::Yes;
                }
                
                LinkedCustAccountTmp.insert();
            }
        }
        ttscommit;
         
        //keep parent table synced
        ttsbegin;
        insert_recordset LinkedCustAccountTmpParent (CustAccountNum, LegalEntity, LinkedCustAccountNum, LinkedLegalEntity, Parent, AddressOnly)
                select CustAccountNum, LegalEntity, LinkedCustAccountNum, LinkedLegalEntity, Parent, AddressOnly
                from    LinkedCustAccountTmp;

        ttscommit;

        //are there any LinkedCustAccountNum (ie Parent account) that dont have their own record? Will need one for Addressing
        ttsbegin;

        while select LinkedCustAccountNum, LinkedLegalEntity
            from    LinkedCustAccountTmpParent
            group by LinkedCustAccountNum, LinkedLegalEntity
            where LinkedCustAccountTmpParent.Parent == NoYes::No
        {
            select firstonly RecId
                from    LinkedCustAccountTmp
                where   LinkedCustAccountTmp.CustAccountNum         == LinkedCustAccountTmpParent.LinkedCustAccountNum
                &&      LinkedCustAccountTmp.LegalEntity            == LinkedCustAccountTmpParent.LinkedLegalEntity
                &&      LinkedCustAccountTmp.Parent                 == NoYes::Yes;

            if(!LinkedCustAccountTmp.RecId)
            {
                //create parent 'Address only' record
                LinkedCustAccountTmp.clear();
                LinkedCustAccountTmp.CustAccountNum         = LinkedCustAccountTmpParent.LinkedCustAccountNum;
                LinkedCustAccountTmp.LegalEntity            = LinkedCustAccountTmpParent.LinkedLegalEntity;
                LinkedCustAccountTmp.LinkedCustAccountNum   = LinkedCustAccountTmpParent.LinkedCustAccountNum;
                LinkedCustAccountTmp.LinkedLegalEntity      = LinkedCustAccountTmpParent.LinkedLegalEntity;
                LinkedCustAccountTmp.Parent                 = NoYes::Yes;
                LinkedCustAccountTmp.AddressOnly            = NoYes::Yes;
                LinkedCustAccountTmp.insert();
            }
        }

        ttscommit;

        //keep parent table synced
        ttsbegin;
        insert_recordset LinkedCustAccountTmpParent (CustAccountNum, LegalEntity, LinkedCustAccountNum, LinkedLegalEntity, Parent, AddressOnly)
            select CustAccountNum, LegalEntity, LinkedCustAccountNum, LinkedLegalEntity, Parent, AddressOnly
            from    LinkedCustAccountTmp
            where   LinkedCustAccountTmp.AddressOnly == NoYes::yes;

        ttscommit;

    }

/// <summary>
/// Gets <c>UseMultithread</c> value of the <c>CustAccountStatementExtContract</c> class.
/// </summary>
/// <returns>A boolean value which contains user input on whether the report printing should run in multiple threads for the current run.
/// </returns>
protected boolean canMultithread()
{
    return this.parmContract().parmUseMultithread();
}

/// <summary>
/// Gets the Contract class.
/// </summary>
/// <returns>Contract class </returns>
protected METCustActivityStatementContract parmContract()
{
    if (!contract)
    {
        contract = this.parmReportContract().parmRdpContract() as METCustActivityStatementContract;
    }
    return contract;
}

/// <summary>
/// Returns the parent query and makes sure it is initilized.
/// </summary>
/// <returns>
/// The parent query.
/// </returns>
protected Query batchParentQuery()
{
    Query parentQuery = super();
    parentQuery.allowCrossCompany(false);
    return parentQuery;
}

/// <summary>
/// Determines if the report printing supports multi-threading.
/// </summary>
/// <returns>A boolean value which specifies if printing of this report can be done in multiple threads. </returns>
public boolean isMultithreadable()
{
    return true;
}

/// <summary>
/// Needs to be overriden in order for multithreading to be implemented.
/// Returns a new instance of the <c>METCustActivityStatementController</c> class that needs to be multithreaded.
/// </summary>
/// <returns>
/// Returns a new instance of the report class that needs to be multithreaded.
/// </returns>
protected SrsPrintMgmtController newInstance()
{
    return new METCustActivityStatementController();
}

/// <summary>
/// Specifies if the batch task is retryable for transient exceptions or not.
/// </summary>
/// <returns>
/// If true is returned, the batch task is retryable, otherwise it is not.
/// </returns>
[Hookable(false)]
public final boolean isRetryable()
{
    return true;
}

    /// <summary>
    /// Returns true if there are transaction for the selected range, else false.
    /// </summary>
    /// <param name = "_custTable">customer record</param>
    /// <param name = "_dataAreaId">Legal entity</param>
    /// <returns>
    /// Returns true if there are transaction for the selected range, else false.
    /// </returns>
    public boolean preProcessCustomer(CustTable _custTable, SelectableDataArea _dataAreaId)
    {
        CustTrans custTrans;
        boolean   processCustomer = false;

        changecompany(_dataAreaId)
        {
            //check if invoice or payment transactions exist for the give contract parameters.
            while select firstonly RecId from custTrans
            where custTrans.AccountNum == _custTable.AccountNum
                && custTrans.TransDate >= contract.parmFromDate()
                && custTrans.TransDate <= contract.parmToDate()
                && custTrans.TransType != LedgerTransType::Settlement
            {
                processCustomer = true;
            }
        }
        return processCustomer;
    }

    /// <summary>
    /// MPJ_11539 - kscerri - 08/04/2021
    /// Calculates GST per trans line according to report parameter
    /// </summary>
    /// <param name = "_voucher">cust voucher</param>
    /// <param name = "_transDate">cust trans date</param>
    /// <returns>total gst</returns>
    public TaxAmountCur calculateGST(Voucher _voucher, TransDate _transDate)
    {
        TaxTrans        taxTrans;
        TaxAmountCur    calcGST;
        List            list  = new List(Types::String);
        ListEnumerator  enumerator;
        str             TaxCode;

        List = contract.parmSalesTaxCode();
        enumerator = list.getEnumerator();
        enumerator.reset();
        
        while(enumerator.moveNext())
        {
            taxCode = enumerator.current();

            select sum(taxAmountCur)
            from    taxTrans
            where   taxTrans.Voucher    == _voucher
            &&      taxTrans.TransDate  == _transDate
            &&      taxTrans.TaxCode    == taxCode;

            calcGST = calcGST + (-taxTrans.taxAmountCur);
        }

        return calcGST;
    }
